import { NonRetryableError } from "cloudflare:workflows";

export interface Page {
  title: string;
  markdown: string;
}

export const fetchPage = async (env: Cloudflare.Env, url: string): Promise<Page> => {
  const response = await fetch(`${env.FIRECRAWL_BASE}/v2/scrape`, {
    method: "POST",
    headers: { authorization: `Bearer ${env.FIRECRAWL_API_KEY}`, "content-type": "application/json" },
    body: JSON.stringify({ url, formats: ["rawHtml", "markdown"], onlyMainContent: true }),
  });

  if (!response.ok) {
    throw new Error(`firecrawl ${response.status}`);
  }

  const body = (await response.json()) as { data: { markdown: string; metadata?: { title?: string } } };
  const firstHeading = body.data.markdown.match(/^# (.+)$/m)?.[1];

  return { title: body.data.metadata?.title ?? firstHeading ?? url, markdown: body.data.markdown };
};

export const IMAGE_PROMPT = (title: string, alt: string | null) =>
  `You are describing an image from a technical article for someone listening to the article who cannot see it.\n\nWrite exactly ONE sentence naming what the image SHOWS.\n\nRules:\n- Be specific, never categorical. Read a chart's axes and its trend, name a screenshot's on-screen elements and the action taken, describe a photo's subject and setting. Never write only "a chart", "a screenshot", or "a photo".\n- Begin the sentence with the thing shown. Never begin with "This", "The image", "An image of", "A picture of", or any preamble, and never use the word "This" anywhere in the sentence.\n- Describe only what is visibly there. Do not name any person, organization, company, brand, product, place, or region unless that exact name appears as written text inside the image.\n- Do not state what the image means or its role in the article. One sentence of visible content, with no second sentence.\n\nArticle title: ${title}\n\nThe alt text below is often wrong, empty, or SEO filler; use it only where it matches what you see and ignore it otherwise.\nAlt text: ${alt ?? "(none)"}`;

export const describeImage = async (env: Cloudflare.Env, image: ItemParams["image"]): Promise<string> => {
  const response = await fetch(
    `${env.GEMINI_BASE}/v1beta/models/gemini-3.5-flash-lite:generateContent`,
    {
      method: "POST",
      headers: { "x-goog-api-key": env.GEMINI_API_KEY, "content-type": "application/json" },
      body: JSON.stringify({
        contents: [
          {
            parts: [
              { text: IMAGE_PROMPT(image.title, image.alt) },
              { inlineData: { data: image.data, mimeType: image.mimeType } },
            ],
            role: "user",
          },
        ],
        generationConfig: {
          responseMimeType: "application/json",
          responseSchema: { properties: { spoken: { type: "STRING" } }, required: ["spoken"], type: "OBJECT" },
        },
      }),
    },
  );

  // 429 and 5xx are worth the step's retries; any other 4xx will not get better
  if (response.status >= 400 && response.status < 500 && response.status !== 429) {
    throw new NonRetryableError(`gemini ${response.status}`);
  }

  if (!response.ok) {
    throw new Error(`gemini ${response.status}`);
  }

  const body = (await response.json()) as { candidates: { content: { parts: { text: string }[] } }[] };

  return (JSON.parse(body.candidates[0].content.parts[0].text) as { spoken: string }).spoken;
};

export const spawnTts = async (env: Cloudflare.Env, text: string): Promise<string> => {
  const response = await fetch(`${env.TTS_BASE}/submit`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ text, voice: "af_heart" }),
  });

  if (!response.ok) {
    throw new Error(`tts submit ${response.status}`);
  }

  return ((await response.json()) as { call_id: string }).call_id;
};

export interface TtsResult {
  audio: ArrayBuffer;
  duration: number;
}

export const pollTts = async (env: Cloudflare.Env, callId: string): Promise<TtsResult | null> => {
  const response = await fetch(`${env.TTS_BASE}/result/${callId}`);

  if (response.status === 202) {
    return null;
  }

  if (!response.ok) {
    throw new Error(`tts result ${response.status}`);
  }

  return { audio: await response.arrayBuffer(), duration: Number(response.headers.get("x-duration")) };
};
