import { WorkflowEntrypoint, type WorkflowEvent, type WorkflowStep } from "cloudflare:workers";
import { resolveWorld } from "./world.ts";

export interface ItemOutput {
  status: "ready";
  title: string;
  imageSpoken: string;
  audioKey: string;
  duration: number;
  polls: number;
}

const MAX_POLLS = 20;

const setStatus = (db: D1Database, itemId: string, status: string) =>
  db.prepare("UPDATE items SET status = ? WHERE id = ?").bind(status, itemId).run();

export class ItemWorkflow extends WorkflowEntrypoint<Cloudflare.Env, ItemParams> {
  async run(event: WorkflowEvent<ItemParams>, step: WorkflowStep): Promise<ItemOutput> {
    const { itemId, url, image } = event.payload;
    const world = resolveWorld(this.env);

    const page = await step.do(
      "fetch page",
      { retries: { limit: 2, delay: "5 seconds", backoff: "constant" } },
      async () => {
        const fetched = await world.fetchPage(url);

        await this.env.DB.prepare("UPDATE items SET status = 'fetched', title = ? WHERE id = ?")
          .bind(fetched.title, itemId)
          .run();

        return { title: fetched.title, text: fetched.markdown.slice(0, 2000) };
      },
    );

    const imageSpoken = await step.do(
      "describe image",
      { retries: { limit: 3, delay: "10 seconds", backoff: "exponential" } },
      async () => {
        const spoken = await world.describeImage(image);

        await this.env.DB.prepare("UPDATE items SET status = 'described', image_spoken = ? WHERE id = ?")
          .bind(spoken, itemId)
          .run();

        return spoken;
      },
    );

    const callId = await step.do("spawn tts", async () => {
      const id = await world.spawnTts(`${page.title}. ${imageSpoken} ${page.text}`);

      await this.env.DB.prepare("UPDATE items SET status = 'synthesizing', tts_call_id = ? WHERE id = ?")
        .bind(id, itemId)
        .run();

      return id;
    });

    let audio: { key: string; duration: number } | null = null;
    let polls = 0;

    while (audio == null) {
      if (polls === MAX_POLLS) {
        throw new Error(`tts did not finish after ${MAX_POLLS} polls`);
      }

      await step.sleep("wait for tts", "30 seconds");
      polls += 1;

      // the audio is larger than a step result may be, so it goes to R2 inside the step that downloads it
      audio = await step.do("poll tts", async () => {
        const result = await world.pollTts(callId);

        if (result == null) {
          return null;
        }

        const key = `audio/${itemId}.wav`;
        await this.env.BUCKET.put(key, result.audio, { httpMetadata: { contentType: "audio/wav" } });

        return { key, duration: result.duration };
      });
    }

    await step.do("write result", async () => {
      await this.env.DB.prepare("UPDATE items SET status = 'ready', audio_key = ?, duration = ? WHERE id = ?")
        .bind(audio.key, audio.duration, itemId)
        .run();
    });

    return { status: "ready", title: page.title, imageSpoken, audioKey: audio.key, duration: audio.duration, polls };
  }
}

export { setStatus };
