import { parse } from "yaml";

export interface Interaction {
  method: string;
  uri: string;
  body: string | null;
  status: number;
  headers: Record<string, string>;
  responseBody: string;
}

interface RawInteraction {
  request: { method: string; uri: string; body: string | null };
  response: { status: { code: number }; headers?: Record<string, string[]>; body: { string: string } };
}

export const loadCassette = (yamlText: string): Interaction[] =>
  (parse(yamlText) as { interactions: RawInteraction[] }).interactions.map(({ request, response }) => ({
    method: request.method.toUpperCase(),
    uri: request.uri,
    body: request.body,
    status: response.status.code,
    headers: Object.fromEntries(Object.entries(response.headers ?? {}).map(([name, values]) => [name, values[0]])),
    responseBody: response.body.string,
  }));

export interface ReplayOptions {
  matchBody?: boolean;
  rewrite?: (uri: string) => string;
}

const sameJson = (left: string | null, right: string | null) => {
  try {
    return JSON.stringify(JSON.parse(left ?? "null")) === JSON.stringify(JSON.parse(right ?? "null"));
  } catch {
    return left === right;
  }
};

// interactions are consumed in recorded order, so a repeated identical request replays a poll or retry sequence
export const createReplayer = (interactions: Interaction[], options: ReplayOptions = {}) => {
  const remaining = [...interactions];
  const misses: string[] = [];

  const replay = async (request: Request): Promise<Response | null> => {
    const uri = options.rewrite?.(request.url) ?? request.url;
    const body = request.method === "GET" ? null : await request.clone().text();
    const index = remaining.findIndex(
      (interaction) =>
        interaction.method === request.method &&
        interaction.uri === uri &&
        (!options.matchBody || sameJson(interaction.body, body)),
    );

    if (index === -1) {
      misses.push(`${request.method} ${uri}`);
      return null;
    }

    const [hit] = remaining.splice(index, 1);
    const status = hit.status;

    return new Response(status === 202 || status === 204 ? null : hit.responseBody, { status, headers: hit.headers });
  };

  return { replay, remaining, misses };
};
EOF
