import { env } from "cloudflare:workers";
import { HttpResponse, http } from "msw";
import { setupServer } from "msw/node";
import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";
import { createReplayer, type Interaction } from "./cassette.ts";
import { describe429, describeImage, firecrawl, modal } from "./fixtures.ts";
import { readItem, runItem } from "./helpers.ts";

const server = setupServer();
const unhandled: string[] = [];

beforeAll(() => server.listen({ onUnhandledRequest: (request) => void unhandled.push(`${request.method} ${request.url}`) }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

const replayThroughMsw = (interactions: Interaction[], options: Parameters<typeof createReplayer>[1] = {}) => {
  const replayer = createReplayer(interactions, options);

  server.use(
    http.all("*", async ({ request }) => (await replayer.replay(request)) ?? HttpResponse.text("no cassette match", { status: 599 })),
  );

  return replayer;
};

describe("msw: fetch interception inside step bodies", () => {
  it("replays the python suite's firecrawl and gemini cassettes and a fabricated modal one through the real step bodies", async () => {
    const replayer = replayThroughMsw([...firecrawl, ...describeImage, ...modal]);
    const run = await runItem("m1", async (m) => {
      await m.disableSleeps();
    });

    const row = await readItem("m1");
    const audio = await env.BUCKET.get("audio/m1.wav");
    console.log("[msw] output", JSON.stringify(run.output), "error", JSON.stringify(run.error), "elapsed", run.elapsedMs);
    console.log("[msw] D1 row", JSON.stringify(row));
    console.log("[msw] R2 object", audio == null ? null : await audio.text(), "misses", replayer.misses, "unhandled", unhandled);

    expect(run.output).toMatchObject({ status: "ready", title: "Herman Melville - Moby-Dick", polls: 3, duration: 12.5 });
    expect(run.output?.imageSpoken).toMatch(/python/i);
    expect(row).toMatchObject({ status: "ready", title: "Herman Melville - Moby-Dick", tts_call_id: "fc-01SPIKE" });
    expect(audio).not.toBeNull();
  });

  it("body matching: the gemini cassette matches the TS client's body as JSON, the firecrawl one does not", async () => {
    const replayer = replayThroughMsw([...firecrawl, ...describeImage, ...modal], { matchBody: true });
    const run = await runItem("m2", async (m) => {
      await m.disableSleeps();
      await m.disableRetryDelays();
    });

    console.log("[msw] matchBody misses", replayer.misses, "error", JSON.stringify(run.error));
    expect(replayer.misses[0]).toMatch(/firecrawl/);
  });

  it("a recorded 429 then 200 drives the step's retry, with retry delays disabled", async () => {
    const replayer = replayThroughMsw([...firecrawl, describe429[0], ...describeImage, ...modal]);
    const run = await runItem("m3", async (m) => {
      await m.disableSleeps();
      await m.disableRetryDelays();
    });

    console.log("[msw] 429 retry output", JSON.stringify(run.output), "elapsed", run.elapsedMs, "remaining", replayer.remaining.length);
    expect(run.output?.status).toBe("ready");
    expect(replayer.remaining.length).toBe(0);
  });

  it("the gateway URL needs a rewrite to replay cassettes recorded against googleapis", async () => {
    const original = env.GEMINI_BASE;
    (env as { GEMINI_BASE: string }).GEMINI_BASE =
      "https://gateway.ai.cloudflare.com/v1/2b32439a1d8fdcdf00a9f7f654a11a6d/nagara-spike/google-ai-studio";
    const replayer = replayThroughMsw([...firecrawl, ...describeImage, ...modal], {
      rewrite: (uri) =>
        uri.replace(/^https:\/\/gateway\.ai\.cloudflare\.com\/v1\/[^/]+\/[^/]+\/google-ai-studio/, "https://generativelanguage.googleapis.com"),
    });

    try {
      const run = await runItem("m4", async (m) => {
        await m.disableSleeps();
      });

      console.log("[msw] via gateway URL output", JSON.stringify(run.output), "misses", replayer.misses);
      expect(run.output?.status).toBe("ready");
    } finally {
      (env as { GEMINI_BASE: string }).GEMINI_BASE = original;
    }
  });
});
