import { readFile } from "node:fs/promises";
import { cloudflareTest, readD1Migrations } from "@cloudflare/vitest-plugin";
import { defineConfig } from "vitest/config";
import { createReplayer, loadCassette } from "./test/cassette.ts";

const migrations = await readD1Migrations("./migrations");
const CASSETTES = "../../../../../api/tests/cassettes";

let replayer = createReplayer([]);
const seen: string[] = [];

// runs in Node: every fetch the worker makes that leaves workerd lands here, and the cassettes are read straight from disk
const outboundService = async (request: Request): Promise<Response> => {
  const url = new URL(request.url);

  if (url.hostname === "cassettes.control") {
    const names = url.searchParams.getAll("name");
    const yamls = await Promise.all(
      names.map((name) => readFile(name.startsWith("./") ? name : `${CASSETTES}/${name}.yaml`, "utf8")),
    );
    replayer = createReplayer(yamls.flatMap(loadCassette));
    seen.length = 0;
    return Response.json({ loaded: replayer.remaining.length });
  }

  if (url.hostname === "cassettes.report") {
    return Response.json({ seen, misses: replayer.misses, remaining: replayer.remaining.length });
  }

  seen.push(`${request.method} ${request.url}`);
  return (await replayer.replay(request)) ?? new Response("no cassette match", { status: 599 });
};

export default defineConfig({
  plugins: [
    cloudflareTest({
      main: "./src/index.ts",
      wrangler: { configPath: "./wrangler.jsonc" },
      miniflare: { bindings: { TEST_MIGRATIONS: migrations }, outboundService },
    }),
  ],
  test: {
    testTimeout: 20_000,
    include: ["test/outbound/**/*.test.ts"],
    setupFiles: ["./test/setup.ts"],
  },
});
